function escapeHtml(value: unknown): string {
  return String(value ?? "").replace(/[&<>"']/g, (char) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" }[char] ?? char));
}

type ControlLink = { title: string; description: string; url: string };

function pageShell(title: string, active: "federation" | "mcp" | "browser" | "hooks" | "skills" | "heartbeat", body: string, script: string, links: readonly ControlLink[] = []): Response {
  const nonce = crypto.randomUUID().replace(/-/g, "");
  const controlLinks = links.map((link) => `<a class="link" href="${escapeHtml(link.url)}"><strong>${escapeHtml(link.title)}</strong><span>${escapeHtml(link.description)}</span></a>`).join("");
  const html = `<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>${title}</title><style nonce="${nonce}">
:root{--paper:#fbfaf7;--ink:#171613;--muted:#77736d;--line:#d9d5cf;--accent:#cc7d5e;--soft:#f3eee8;--ok:#557263;--danger:#923f2f}*{box-sizing:border-box}body{margin:0;background:var(--paper);color:var(--ink);font-family:"Anthropic Serif","Noto Serif SC",Georgia,serif;letter-spacing:0}.shell{min-height:100vh;display:grid;grid-template-columns:190px minmax(0,1fr) 270px}.rail{padding:30px 22px;border-right:1px solid var(--line);position:sticky;top:0;height:100vh}.right{border:0;border-left:1px solid var(--line)}.brand{font-size:13px;color:var(--accent);font-weight:700;text-transform:uppercase;margin-bottom:30px}.nav{display:grid;gap:6px}.nav a{color:var(--muted);padding:10px 8px;text-decoration:none}.nav a.active{color:var(--ink);border-left:2px solid var(--accent)}main{padding:34px 38px 56px;min-width:0}header{display:flex;justify-content:space-between;align-items:end;gap:20px;border-bottom:1px solid var(--line);padding-bottom:20px;margin-bottom:28px}h1{font-size:38px;font-weight:500;margin:2px 0 0}h2{font-size:19px;margin:0 0 12px}.meta,.hint{color:var(--muted);font-size:12px;line-height:1.6}.section{border-top:2px solid var(--ink);padding-top:18px;margin-top:30px}.stats{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));border-top:1px solid var(--line);border-bottom:1px solid var(--line)}.stat{padding:16px 14px;border-right:1px solid var(--line)}.stat:last-child{border-right:0}.stat strong{display:block;font-size:22px;font-weight:500}.rows{border-top:1px solid var(--line)}.row{display:grid;grid-template-columns:minmax(140px,1fr) minmax(100px,.7fr) auto;gap:18px;align-items:center;padding:14px 0;border-bottom:1px solid var(--line)}.row strong,.row span{overflow-wrap:anywhere}.state{color:var(--ok)}.state.failed,.state.disabled{color:var(--danger)}.chips{display:flex;gap:7px;flex-wrap:wrap}.chip{border:1px solid var(--line);padding:5px 7px;font-size:11px}.link{display:block;color:var(--ink);text-decoration:none;padding:15px 0;border-bottom:1px solid var(--line)}.link strong,.link span{display:block}.link span{color:var(--muted);font-size:11px;margin-top:4px}form{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:14px 18px}.field{display:grid;gap:7px}.field.wide{grid-column:1/-1}.field label{font-size:12px;font-weight:600}.field input,.field select,.field textarea{width:100%;border:1px solid var(--line);background:var(--paper);padding:10px;color:var(--ink);border-radius:3px;font:inherit}.field textarea{min-height:88px;resize:vertical}.actions{display:flex;align-items:center;gap:9px;flex-wrap:wrap;margin-top:18px}.action{border:1px solid var(--ink);background:transparent;color:var(--ink);padding:9px 13px;border-radius:3px;cursor:pointer;font:inherit}.action.primary{background:var(--ink);color:var(--paper)}.action.danger{color:var(--danger);border-color:var(--accent)}.toast{position:fixed;left:50%;bottom:24px;transform:translateX(-50%);background:var(--ink);color:var(--paper);padding:10px 14px;display:none;z-index:10}.toast.show{display:block}@media(max-width:1000px){.shell{grid-template-columns:150px minmax(0,1fr)}.right{position:static;height:auto;grid-column:1/-1;border-left:0;border-top:1px solid var(--line)}.stats{grid-template-columns:repeat(2,1fr)}}@media(max-width:680px){.shell{display:block}.rail{position:static;height:auto;border-right:0;border-bottom:1px solid var(--line);padding:18px}main{padding:24px 18px}.stats,form{grid-template-columns:1fr}.stat{border-right:0;border-bottom:1px solid var(--line)}.row{grid-template-columns:1fr auto}.row .meta{grid-column:1/-1}header{align-items:flex-start;flex-direction:column}h1{font-size:30px}}
.chip{display:inline-flex;align-items:center;gap:6px}.chip button{border:0;background:transparent;color:var(--danger);cursor:pointer;font:inherit;padding:0 2px}
</style></head><body><div class="shell"><aside class="rail"><div class="brand">Operia / Agent</div><nav class="nav"><a href="/">工具目录</a><a class="${active === "federation" ? "active" : ""}" href="/control">全域控制</a><a class="${active === "mcp" ? "active" : ""}" href="/tools/mcp">MCP</a><a class="${active === "browser" ? "active" : ""}" href="/tools/browser">Browser & Web</a><a class="${active === "skills" ? "active" : ""}" href="/tools/skills">Skills</a><a class="${active === "heartbeat" ? "active" : ""}" href="/tools/heartbeat">Heartbeat Studio</a><a class="${active === "hooks" ? "active" : ""}" href="/tools/hooks">Hooks & Housekeeping</a><a href="/tools/voice">ElevenLabs Voice</a></nav></aside><main>${body}</main><aside class="rail right"><div class="brand">Control Pages</div>${controlLinks}</aside></div><div class="toast" id="toast" role="status"></div><script nonce="${nonce}">${script}</script></body></html>`;
  return new Response(html, { headers: { "content-type": "text/html; charset=utf-8", "cache-control": "no-store", "content-security-policy": `default-src 'none'; base-uri 'none'; frame-ancestors 'none'; script-src 'nonce-${nonce}'; style-src 'nonce-${nonce}'; connect-src 'self'`, "x-frame-options": "DENY", "x-robots-tag": "noindex" } });
}

const sharedScript = `const API='/api/agent/control';const $=s=>document.querySelector(s);const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));function toast(m){const n=$('#toast');n.textContent=m;n.classList.add('show');setTimeout(()=>n.classList.remove('show'),2200)}async function api(path,options={}){const response=await fetch(API+path,{credentials:'same-origin',...options,headers:{accept:'application/json',...(options.headers||{})}});const data=await response.json();if(!response.ok)throw new Error(data.message||data.error||response.statusText);return data}`;

export function renderFederatedControlPage(links: readonly ControlLink[] = []): Response {
  const body = `<header><div><div class="meta">FEDERATED CONTROL / READ PROJECTION</div><h1>全域控制</h1></div><span class="state" id="registry">正在连接</span></header><section><h2>Agent 权威参数</h2><div class="rows" id="agent-values"><div class="row"><span class="meta">正在读取</span></div></div></section><section class="section"><h2>Memory 继承参数</h2><div class="rows" id="memory-values"><div class="row"><span class="meta">正在读取</span></div></div></section><section class="section"><h2>所有权说明</h2><div class="rows"><div class="row"><strong>本页是聚合投影</strong><span class="meta">修改入口始终位于参数 owner；owner 不可达时不会伪造当前值。</span><span class="state">read only</span></div></div></section>`;
  const script = `${sharedScript};function rows(values){return(values||[]).map(x=>{const d=x.definition||{};const c=x.current||{};const key=d.key||x.key;const owner=d.ownerDomain||x.ownerDomain||'unknown';const source=x.effectiveSource||x.source||'owner';const raw=Object.prototype.hasOwnProperty.call(x,'effectiveValue')?x.effectiveValue:c.value;return '<div class="row"><strong>'+esc(d.label||key)+'</strong><span class="meta">'+esc(owner)+' · '+esc(source)+' · '+esc(x.migration||'canonical')+'</span><span class="state">'+esc(typeof raw==='object'?JSON.stringify(raw):raw)+'</span></div>'}).join('')||'<div class="row"><span class="meta">暂无参数</span></div>'}async function load(){const d=await api('/federation');$('#registry').textContent=d.registryVersion||'unknown';$('#agent-values').innerHTML=rows(d.own?.values);const m=d.memory||{};$('#memory-values').innerHTML=m.status==='ready'?rows(m.values):'<div class="row"><strong>Memory</strong><span class="meta">'+esc(m.reason||m.httpStatus||'owner unavailable')+'</span><span class="state disabled">unavailable</span></div>'}load().catch(e=>{$('#registry').textContent='unavailable';$('#registry').classList.add('disabled');toast(e.message)});`;
  return pageShell("Operia 全域控制", "federation", body, script, links);
}

export function renderMcpWorkbenchPage(csrfToken = "", links: readonly ControlLink[] = []): Response {
  const body = `<header><div><div class="meta">INHERITED OWNER / MCP GATEWAY</div><h1>MCP</h1></div><div class="actions"><a class="action" href="https://mcp.example.com/admin">打开 Gateway 真源</a><span class="state" id="status">正在连接</span></div></header><div class="stats"><div class="stat"><strong id="revision">-</strong><span class="meta">Owner revision</span></div><div class="stat"><strong id="providerCount">-</strong><span class="meta">Providers</span></div><div class="stat"><strong id="enabledCount">-</strong><span class="meta">Enabled tools</span></div><div class="stat"><strong id="callableCount">-</strong><span class="meta">Agent callable</span></div></div><section class="section" id="elicitationSection"><h2>MCP 请求</h2><p class="hint">表单只接受 MCP 协议允许的非敏感基础字段；外部授权链接不会由 Agent 预取。</p><div id="elicitations" class="rows"><div class="row"><span class="meta">暂无待处理请求</span></div></div></section><section class="section"><h2>Gateway-owned Providers</h2><p class="hint">这里修改的是 mcp.example.com 的同一份 owner state；Agent 不保存第二套开关。风险策略、审批、幂等和结果清洗仍由 Agent 执行。</p><div id="providers"></div></section>`;
  const script = `${sharedScript};let csrf=${JSON.stringify(csrfToken)},snapshot=null;function mutation(path,options){return api(path,{...options,headers:{'content-type':'application/json','x-csrf-token':csrf,...(options.headers||{})}})}function render(d){snapshot=d;$('#status').textContent=d.status||'unavailable';$('#status').classList.toggle('disabled',d.status!=='current');$('#revision').textContent=d.revision??'-';const providers=d.providers||[];const tools=providers.flatMap(p=>p.tools||[]);$('#providerCount').textContent=providers.length;$('#enabledCount').textContent=tools.filter(t=>t.enabled).length;$('#callableCount').textContent=tools.filter(t=>t.agentCallable).length;$('#providers').innerHTML=providers.map(p=>'<section class="section"><h2>'+esc(p.label)+' <span class="meta">'+esc(p.id)+' · '+esc(p.status)+' · revision '+esc(p.ownerRevision)+'</span></h2><div class="rows">'+(p.tools||[]).map(t=>'<div class="row"><div><strong>'+esc(t.name)+'</strong><span class="meta">'+esc(t.description||'')+'</span></div><span class="meta">'+esc(t.risk||p.risk)+(t.requiresConfirmation?' · approval':'')+' · '+(t.agentCallable?'Agent callable':'not projected')+'</span><button class="action tool-toggle" data-provider="'+esc(p.id)+'" data-tool="'+esc(t.name)+'" data-enabled="'+(t.enabled?'1':'0')+'" type="button">'+(t.enabled?'停用':'启用')+'</button></div>').join('')+'</div></section>').join('')||'<div class="rows"><div class="row"><span class="meta">暂无 Gateway Provider</span></div></div>'}function field(ticket,key,definition,required){const id='el-'+ticket.id+'-'+key;const label='<label for="'+esc(id)+'">'+esc(definition.title||key)+(required?' *':'')+'</label>';if(Array.isArray(definition.enum))return '<div class="field">'+label+'<select id="'+esc(id)+'" data-key="'+esc(key)+'">'+definition.enum.map(v=>'<option value="'+esc(v)+'">'+esc(v)+'</option>').join('')+'</select></div>';if(definition.type==='boolean')return '<div class="field">'+label+'<select id="'+esc(id)+'" data-key="'+esc(key)+'"><option value="true">是</option><option value="false">否</option></select></div>';const type=definition.type==='number'||definition.type==='integer'?'number':definition.format==='email'?'email':definition.format==='uri'?'url':definition.format==='date'?'date':definition.format==='date-time'?'datetime-local':'text';return '<div class="field">'+label+'<input id="'+esc(id)+'" data-key="'+esc(key)+'" data-type="'+esc(definition.type||'string')+'" type="'+type+'" '+(required?'required ':'')+'maxlength="'+esc(definition.maxLength||4096)+'"></div>'}function elicitationHistory(ticket){const labels={expired:'已过期',attention_required:'需要检查',accepted:'已接受',declined:'已拒绝',cancelled:'已取消'};const notes={expired:'票据已失效，原任务不会自动重放',attention_required:'任务状态异常，请通过任务结果恢复查看 checkpoint',accepted:'决定已消费，任务已继续',declined:'已拒绝，未执行后续副作用',cancelled:'已取消，未执行后续副作用'};const failed=!['accepted'].includes(ticket.status);return '<div class="row" id="elicitation-'+esc(ticket.id)+'"><div><strong>'+esc(ticket.providerId)+' / '+esc(ticket.toolName)+'</strong><span class="meta">'+esc(ticket.message)+'</span></div><span class="meta">Task '+esc(ticket.taskId)+' · '+esc(notes[ticket.status]||'只读历史')+'</span><span class="state '+(failed?'failed':'')+'">'+esc(labels[ticket.status]||ticket.status)+'</span></div>'}
function renderElicitations(rows){$('#elicitations').innerHTML=(rows||[]).map(ticket=>{if(!ticket.actionable)return elicitationHistory(ticket);if(ticket.mode==='url')return '<div class="row" id="elicitation-'+esc(ticket.id)+'"><div><strong>'+esc(ticket.providerId)+' / '+esc(ticket.toolName)+'</strong><span class="meta">'+esc(ticket.message)+'</span></div><span class="meta">expires '+esc(ticket.expiresAt)+'</span><span><a class="action" href="'+esc(ticket.url)+'" target="_blank" rel="noreferrer">打开授权</a> <button class="action elicitation-action" data-id="'+esc(ticket.id)+'" data-action="accept" type="button">已完成</button> <button class="action danger elicitation-action" data-id="'+esc(ticket.id)+'" data-action="decline" type="button">拒绝</button></span></div>';const schema=ticket.requestedSchema||{},properties=schema.properties||{},required=new Set(schema.required||[]);return '<form class="elicitation-form" id="elicitation-'+esc(ticket.id)+'" data-id="'+esc(ticket.id)+'"><div class="field wide"><strong>'+esc(ticket.providerId)+' / '+esc(ticket.toolName)+'</strong><span class="meta">'+esc(ticket.message)+' · expires '+esc(ticket.expiresAt)+'</span></div>'+Object.entries(properties).map(([key,definition])=>field(ticket,key,definition,required.has(key))).join('')+'<div class="actions wide"><button class="action primary" type="submit">提交并继续</button><button class="action danger elicitation-action" data-id="'+esc(ticket.id)+'" data-action="cancel" type="button">取消</button></div></form>'}).join('')||'<div class="row"><span class="meta">最近 24 小时没有 MCP 请求</span></div>'}
async function load(){const [d,e]=await Promise.all([api('/mcp'),api('/mcp/elicitations')]);if(!csrf&&d.csrfToken)csrf=d.csrfToken;render(d);renderElicitations(e.elicitations||[]);const target=location.hash.match(/^#elicitation=(elc_[a-f0-9]{24})$/)?.[1];if(target)document.getElementById('elicitation-'+target)?.scrollIntoView({block:'center'})}async function decide(id,action,content){await mutation('/mcp/elicitations/'+encodeURIComponent(id)+'/decision',{method:'POST',body:JSON.stringify({action,content})});toast('MCP 请求已处理，原任务正在恢复');await load()}$('#providers').addEventListener('click',async e=>{const b=e.target.closest('.tool-toggle');if(!b)return;if(!snapshot?.etag){toast('Owner revision 暂不可用');return}b.disabled=true;try{const d=await mutation('/mcp/tools',{method:'PATCH',headers:{'if-match':snapshot.etag},body:JSON.stringify({provider:b.dataset.provider,tool:b.dataset.tool,enabled:b.dataset.enabled!=='1'})});render(d);toast('Gateway owner state 已更新')}catch(error){toast(error.message);await load()}});$('#elicitations').addEventListener('click',async e=>{const b=e.target.closest('.elicitation-action');if(!b)return;b.disabled=true;try{await decide(b.dataset.id,b.dataset.action)}catch(error){toast(error.message);b.disabled=false}});$('#elicitations').addEventListener('submit',async e=>{const form=e.target.closest('.elicitation-form');if(!form)return;e.preventDefault();const content={};for(const input of form.querySelectorAll('[data-key]')){let value=input.value;if(input.dataset.type==='number'||input.dataset.type==='integer')value=Number(value);else if(input.tagName==='SELECT'&&(value==='true'||value==='false'))value=value==='true';content[input.dataset.key]=value}try{await decide(form.dataset.id,'accept',content)}catch(error){toast(error.message)}});load().catch(error=>{$('#status').textContent='unavailable';$('#status').classList.add('disabled');toast(error.message)});`;
  return pageShell("Operia MCP", "mcp", body, script, links);
}

export function renderBrowserWorkbenchPage(csrfToken = "", links: readonly ControlLink[] = []): Response {
  const quickActionNames = "browser_markdown · browser_links · browser_scrape · browser_extract";
  const body = `<header><div><div class="meta">TOOL WORKBENCH / CLOUDFLARE</div><h1>Browser & Web</h1></div><span class="state" id="status">正在连接</span></header><div class="stats"><div class="stat"><strong id="used">-</strong><span class="meta">今日 Browser 时间</span></div><div class="stat"><strong id="budget">-</strong><span class="meta">每日安全预算</span></div><div class="stat"><strong id="cache">-</strong><span class="meta">Tool cache</span></div><div class="stat"><strong id="planner">-</strong><span class="meta">Planner calls</span></div></div><section class="section"><h2>Providers</h2><div class="rows" id="providers"></div></section><section class="section"><h2>域名 allowlist</h2><div class="chips" id="domains"></div></section><section class="section"><h2>执行面</h2><div class="rows"><div class="row"><strong>Quick Actions</strong><span class="meta">Markdown · links · scrape · schema extract</span><span class="state">read</span></div><div class="row"><strong>browser_task</strong><span class="meta">类型化动作 · 站点档案 · 可撤销租约</span><span class="state" id="taskLeases">checking</span></div><div class="row"><strong>browser_execute</strong><span class="meta">兼容：one-shot · dynamic · reuse</span><span class="state" id="interactive">checking</span></div><div class="row"><strong>Human handoff</strong><span class="meta">高风险兼容执行通过 Live View 审批恢复</span><span class="state">approval</span></div></div></section><section class="section"><h2>站点档案</h2><div class="rows" id="siteProfiles"><div class="row"><span class="meta">暂无站点档案</span></div></div></section><section class="section"><h2>任务租约</h2><div class="rows" id="taskLeasesRows"><div class="row"><span class="meta">暂无任务租约</span></div></div></section><section class="section"><h2>Sessions</h2><div class="rows" id="sessions"><div class="row"><span class="meta">暂无持久 Session</span></div></div></section><section class="section"><h2>交互执行与 Live View</h2><div class="rows" id="executions"><div class="row"><span class="meta">暂无交互执行</span></div></div></section><section class="section"><h2>Site Adapters</h2><div class="rows" id="adapters"><div class="row"><span class="meta">暂无 Adapter</span></div></div></section><section class="section"><h2>受限 Skills</h2><div class="rows" id="skills"><div class="row"><span class="meta">暂无 Skill</span></div></div></section><section class="section"><h2>最近运行</h2><div class="rows" id="runs"><div class="row"><span class="meta">暂无运行</span></div></div></section><section class="section"><h2>结构化日志</h2><div class="rows" id="events"><div class="row"><span class="meta">暂无事件</span></div></div></section>`;
  const script = `${sharedScript};let csrf=${JSON.stringify(csrfToken)};let snapshot=null;function mutation(path,options){return api(path,{...options,headers:{'content-type':'application/json','x-csrf-token':csrf,...(options.headers||{})}})}function pendingUrl(row){try{const p=JSON.parse(row.pending_json||'[]');return p[0]?.args?.liveViewUrl||''}catch{return''}}async function load(){const d=await api('/bootstrap');snapshot=d;const b=d.browser||{};if(!csrf&&d.csrfToken)csrf=String(d.csrfToken);$('#status').textContent=b.enabled?'ready':'disabled';$('#status').classList.toggle('disabled',!b.enabled);$('#interactive').textContent=b.interactiveEnabled?'enabled':'disabled';$('#interactive').classList.toggle('disabled',!b.interactiveEnabled);$('#taskLeases').textContent=b.taskLeasesEnabled?'enabled':'disabled';$('#taskLeases').classList.toggle('disabled',!b.taskLeasesEnabled);$('#used').textContent=((b.usedTodayMs||0)/1000).toFixed(1)+'s';$('#budget').textContent=((b.dailyBudgetMs||0)/60000).toFixed(0)+'m';$('#cache').textContent=(d.cache?.entries||0)+' / '+(d.cache?.hits||0);$('#planner').textContent=String(d.runtime?.limits?.plannerCallsToday||0);const p=b.providerStatus||{};$('#providers').innerHTML=[['Browser Run',p.browserRun],['Worker Loader',p.workerLoader],['GLM planner',p.planner],['Private R2',p.r2]].map(x=>'<div class="row"><strong>'+esc(x[0])+'</strong><span class="meta">'+esc(typeof x[1]==='string'?x[1]:'Cloudflare binding')+'</span><span class="state '+(x[1]?'':'disabled')+'">'+(x[1]?'ready':'disabled')+'</span></div>').join('');renderDomains(b);$('#siteProfiles').innerHTML=(b.siteProfiles||[]).map(r=>'<div class="row"><strong>'+esc(r.label)+' · '+esc(r.maximum_mode)+'</strong><span class="meta">'+esc(r.primary_hosts_json)+' → '+esc(r.redirect_hosts_json)+'</span><span class="state">v'+esc(r.revision)+'</span></div>').join('')||'<div class="row"><span class="meta">暂无站点档案</span></div>';$('#taskLeasesRows').innerHTML=(b.taskLeases||[]).map(r=>'<div class="row"><strong>'+esc(r.site_profile_id)+' · '+esc(r.mode)+'</strong><span class="meta">'+esc(r.task_id)+' · '+esc(r.used_logical_steps)+'/'+esc(r.max_logical_steps)+' steps</span><span class="state '+esc(r.state)+'">'+esc(r.state)+'</span></div>').join('')||'<div class="row"><span class="meta">暂无任务租约</span></div>';$('#sessions').innerHTML=(b.sessions||[]).map(r=>'<div class="row"><strong>'+esc(r.mode)+' · '+esc(r.last_url_origin||'unknown')+'</strong><span class="meta">'+esc(r.last_used_at)+' · expires '+esc(r.expires_at)+'</span><span class="state '+esc(r.state)+'">'+esc(r.state)+'</span></div>').join('')||'<div class="row"><span class="meta">暂无持久 Session</span></div>';$('#executions').innerHTML=(b.executions||[]).map(r=>{const live=pendingUrl(r);const buttons=(live?'<button class="action live" data-id="'+esc(r.execution_id)+'" type="button">Live View</button> ':'')+(r.status==='paused'?'<button class="action danger reject" data-id="'+esc(r.execution_id)+'" type="button">拒绝</button> ':'')+(r.mode!=='one-shot'?'<button class="action close" data-id="'+esc(r.execution_id)+'" type="button">关闭 Session</button>':'');return '<div class="row"><strong>'+esc(r.mode)+' · '+esc(r.session_key)+'</strong><span class="meta">'+esc(r.execution_id)+' · '+esc(r.domains_json)+'</span><span><span class="state '+esc(r.status)+'">'+esc(r.status)+'</span> '+buttons+'</span></div>'}).join('')||'<div class="row"><span class="meta">暂无交互执行</span></div>';$('#adapters').innerHTML=(d.siteAdapters||[]).map(a=>'<div class="row"><strong>'+esc(a.key)+'</strong><span class="meta">'+esc((a.domains||[]).join(', '))+' · v'+esc(a.version)+' · '+esc(String(a.sourceHash||'').slice(0,12))+'</span><span class="state '+esc(a.smoke?.status)+'">'+esc(a.riskLevel)+' · '+esc(a.smoke?.status)+'</span></div>').join('')||'<div class="row"><span class="meta">暂无 Adapter</span></div>';$('#skills').innerHTML=(d.skills||[]).map(s=>'<div class="row"><strong>'+esc(s.key)+'</strong><span class="meta">'+esc(s.description)+' · '+esc(String(s.sourceHash||'').slice(0,12))+'</span><span class="state">'+esc(s.kind)+'</span></div>').join('')||'<div class="row"><span class="meta">暂无 Skill</span></div>';$('#runs').innerHTML=(b.runs||[]).map(r=>'<div class="row"><strong>'+esc(r.action)+'</strong><span class="meta">'+esc(r.url_host)+' · '+esc(r.started_at)+'</span><span class="state '+esc(r.status)+'">'+esc(r.status)+' · '+esc(r.browser_ms||0)+'ms</span></div>').join('')||'<div class="row"><span class="meta">暂无运行</span></div>';$('#events').innerHTML=(b.events||[]).map(r=>'<div class="row"><strong>'+esc(r.event_type)+'</strong><span class="meta">'+esc(r.created_at)+' · '+esc(r.detail_json)+'</span><span class="state">audit</span></div>').join('')||'<div class="row"><span class="meta">暂无事件</span></div>'}$('#executions').addEventListener('click',async e=>{const button=e.target.closest('button');if(!button)return;const id=button.dataset.id;try{if(button.classList.contains('live')){const d=await api('/browser/'+encodeURIComponent(id)+'/live');let url=d.live?.targets?.[0]?.url;try{url=url||d.pending?.[0]?.args?.liveViewUrl}catch{}if(!url)throw new Error('Live View 当前不可用');window.open(url,'_blank','noopener');return}if(button.classList.contains('reject'))await mutation('/browser/'+encodeURIComponent(id)+'/reject',{method:'POST',body:'{}'});if(button.classList.contains('close'))await mutation('/browser/'+encodeURIComponent(id)+'/close-session',{method:'POST',body:'{}'});toast('Browser 状态已更新');await load()}catch(error){toast(error.message)}});load().catch(e=>{$('#status').textContent='unavailable';$('#status').classList.add('failed');toast(e.message)});`;
  const editableBody = body.replace('<div class="chips" id="domains"></div>', '<form id="domainForm"><div class="field wide"><label for="domainInput">精确 HTTPS hostname</label><input id="domainInput" type="text" maxlength="253" autocomplete="off" spellcheck="false" placeholder="openpsychometrics.org"></div><div class="actions wide"><button class="action primary" type="submit" title="新增域名">+</button><span class="meta" id="domainMeta">Agent owner store</span></div></form><div class="chips" id="domains"></div>');
  const browserBody = editableBody.replace('<span class="state" id="status">', '<div class="actions"><button class="action" id="smoke" type="button">运行 Smoke</button><button class="action" id="e2e" type="button">交互 E2E</button><a class="action primary" href="https://t.me/<OWNER_BOT_USERNAME>" target="_blank" rel="noreferrer">前往 Telegram 审批</a><span class="state" id="status">').replace('</span></header>', '</span></div></header>').replace('<section class="section"><h2>Site Adapters</h2>', '<section class="section"><h2>交互 E2E 状态</h2><div class="rows" id="e2eState"><div class="row"><span class="meta">尚未运行</span></div></div></section><section class="section"><h2>Site Adapters</h2>');
  const policyBody = browserBody.replace('<section class="section"><h2>执行面</h2>', '<section class="section"><h2>域名 denylist</h2><form id="denyForm"><div class="field wide"><label for="denyInput">精确禁止 hostname</label><input id="denyInput" type="text" maxlength="253" autocomplete="off" spellcheck="false" placeholder="malicious.example"></div><div class="actions wide"><button class="action danger" type="submit" title="新增拒绝域名">+</button><span class="meta" id="denyMeta">Agent owner store</span></div></form><div class="chips" id="denies"></div></section><section class="section"><h2>临时域授权</h2><div class="rows" id="domainGrants"><div class="row"><span class="meta">暂无临时授权</span></div></div></section><section class="section"><h2>域挑战</h2><div class="rows" id="domainChallenges"><div class="row"><span class="meta">暂无域挑战</span></div></div></section><section class="section"><h2>执行面</h2>');
  const recoverySection = `<section class="section" id="taskRecovery"><h2>任务结果恢复</h2><form id="taskRecoveryForm" autocomplete="off"><div class="field wide"><label for="taskIdInput">Task ID</label><input id="taskIdInput" name="task_id" type="text" maxlength="128" pattern="[A-Za-z0-9][A-Za-z0-9._:-]{0,127}" spellcheck="false" placeholder="输入 delegated task ID"></div><div class="actions wide"><button class="action primary" type="submit">读取结果</button><span class="hint">只读读取 Agent owner checkpoint 与 progress snapshot；不会复制或恢复执行。</span></div></form><div class="rows" id="taskRecoveryResult" aria-live="polite"><div class="row"><span class="meta">输入 Task ID 后读取结果</span></div></div></section>`;
  const diagnosticBody = policyBody.replace('<section class="section"><h2>任务租约</h2>', `${recoverySection}<section class="section"><h2>任务租约</h2>`).replace('<section class="section"><h2>结构化日志</h2>', '<section class="section"><h2>Planner 调用</h2><div class="rows" id="plannerRuns"><div class="row"><span class="meta">暂无 Planner 调用</span></div></div></section><section class="section"><h2>结构化日志</h2>');
  const smokeScript = `async function loadE2e(){try{const d=await api('/browser/e2e/latest');$('#e2eState').innerHTML='<div class="row"><strong>'+esc(d.taskStatus)+' · '+esc(d.ticketStatus)+'</strong><span class="meta">workflow '+esc(d.workflowStatus?.status||'unknown')+' · browser '+esc(d.browserExecutionStatus||'unknown')+' · codemode '+esc(d.codemodeExecution?.status||'unknown')+' · side effect '+esc(d.sideEffectStatus||'unknown')+' · '+esc(d.attentionError||d.codemodeExecution?.error||'ready')+'</span><span class="state">'+esc(d.taskId)+'</span></div>'}catch{$('#e2eState').innerHTML='<div class="row"><span class="meta">尚未运行</span></div>'}}$('#smoke').addEventListener('click',async()=>{try{const d=await mutation('/browser/smoke',{method:'POST',body:'{}'});toast('Smoke 通过 · '+d.browserMs+'ms');await load()}catch(error){toast(error.message)}});$('#e2e').addEventListener('click',async()=>{try{await mutation('/browser/e2e/start',{method:'POST',body:'{}'});toast('交互执行已暂停，请前往 Telegram 审批');await Promise.all([load(),loadE2e()])}catch(error){toast(error.message)}});loadE2e();`;
  const domainScript = `function renderDomains(b){const domains=b.domainAllowlist||[];$('#domainMeta').textContent=esc(b.domainAllowlistSource||'owner_store')+' · revision '+esc(b.domainAllowlistRevision||0)+' · 精确 hostname';$('#domains').innerHTML=domains.map(x=>'<span class="chip">'+esc(x)+'<button class="domain-remove" data-domain="'+esc(x)+'" type="button" title="移除 '+esc(x)+'">×</button></span>').join('')||'<span class="meta">deny all</span>'}async function saveDomains(domains){const b=snapshot?.browser||{};try{await mutation('/browser/domain-allowlist',{method:'PUT',headers:{'if-match':'"'+String(b.domainAllowlistRevision||0)+'"'},body:JSON.stringify({domains})});await load()}catch(error){await load();throw error}}$('#domainForm').addEventListener('submit',async e=>{e.preventDefault();const input=$('#domainInput');const domain=input.value.trim().toLowerCase().replace(/\.$/,'');const current=snapshot?.browser?.domainAllowlist||[];if(!domain)return;if(!confirm('允许 Agent Browser 访问 '+domain+'？'))return;try{await saveDomains([...current,domain]);input.value='';toast('域名已加入 allowlist')}catch(error){toast(error.message)}});$('#domains').addEventListener('click',async e=>{const button=e.target.closest('.domain-remove');if(!button)return;const domain=button.dataset.domain;const next=(snapshot?.browser?.domainAllowlist||[]).filter(x=>x!==domain);if(next.length===0&&!confirm('清空后 Browser 将 deny all。继续？'))return;try{await saveDomains(next);toast('域名已移除')}catch(error){toast(error.message)}});`;
  const domainPolicyScript = `function renderDomainPolicy(b){const denies=b.domainDenylist||[];$('#denyMeta').textContent=esc(b.domainDenylistSource||'owner_store')+' · revision '+esc(b.domainDenylistRevision||0)+' · deny 优先';$('#denies').innerHTML=denies.map(x=>'<span class="chip">'+esc(x)+'<button class="deny-remove" data-domain="'+esc(x)+'" type="button" title="移除拒绝 '+esc(x)+'">×</button></span>').join('')||'<span class="meta">暂无永久拒绝</span>';$('#domainGrants').innerHTML=(b.domainGrants||[]).map(g=>'<div class="row"><strong>'+esc(g.hostname)+' · '+esc(g.scope)+'</strong><span class="meta">'+esc(g.task_id)+' · expires '+esc(g.expires_at)+'</span><span><span class="state '+esc(g.status)+'">'+esc(g.status)+'</span> '+(g.status==='active'?'<button class="action danger grant-revoke" data-id="'+esc(g.id)+'" type="button">撤销</button>':'')+'</span></div>').join('')||'<div class="row"><span class="meta">暂无临时授权</span></div>';$('#domainChallenges').innerHTML=(b.domainChallenges||[]).map(c=>'<div class="row"><strong>'+esc(c.source_host||'new session')+' → '+esc(c.target_hosts_json)+'</strong><span class="meta">'+esc(c.task_id)+' · expires '+esc(c.expires_at)+'</span><span class="state '+esc(c.status)+'">'+esc(c.status)+(c.decision_scope?' · '+esc(c.decision_scope):'')+'</span></div>').join('')||'<div class="row"><span class="meta">暂无域挑战</span></div>'}async function saveDenies(domains){const b=snapshot?.browser||{};try{await mutation('/browser/domain-denylist',{method:'PUT',headers:{'if-match':'"'+String(b.domainDenylistRevision||0)+'"'},body:JSON.stringify({domains})});await load()}catch(error){await load();throw error}}$('#denyForm').addEventListener('submit',async e=>{e.preventDefault();const input=$('#denyInput');const domain=input.value.trim().toLowerCase().replace(/\.$/,'');if(!domain)return;if(!confirm('永久拒绝 Agent Browser 访问 '+domain+'？'))return;try{await saveDenies([...(snapshot?.browser?.domainDenylist||[]),domain]);input.value='';toast('域名已加入 denylist')}catch(error){toast(error.message)}});$('#denies').addEventListener('click',async e=>{const button=e.target.closest('.deny-remove');if(!button)return;try{await saveDenies((snapshot?.browser?.domainDenylist||[]).filter(x=>x!==button.dataset.domain));toast('拒绝规则已移除')}catch(error){toast(error.message)}});$('#domainGrants').addEventListener('click',async e=>{const button=e.target.closest('.grant-revoke');if(!button)return;try{await mutation('/browser/domain-grants/'+encodeURIComponent(button.dataset.id)+'/revoke',{method:'POST',body:'{}'});toast('临时授权已撤销');await load()}catch(error){toast(error.message)}});`;
  const plannerScript = `async function loadPlannerRuns(){const d=snapshot||await api('/bootstrap');const rows=d.browser?.plannerRuns||[];$('#plannerRuns').innerHTML=rows.map(r=>'<div class="row"><strong>'+esc(r.task_id)+'</strong><span class="meta">in '+esc(r.input_tokens??'-')+' · out '+esc(r.output_tokens??'-')+' · reasoning '+esc(r.reasoning_tokens??'-')+' · cache '+esc(r.cache_read_tokens??'-')+' · '+esc(r.total_ms||0)+'ms</span><span class="state '+(r.success?'':'failed')+'">'+esc(r.finish_reason||r.error_code||(r.success?'ok':'failed'))+'</span></div>').join('')||'<div class="row"><span class="meta">暂无 Planner 调用</span></div>'}queueMicrotask(()=>loadPlannerRuns().catch(()=>{}));`;
  const recoveryScript = `const TASK_ID_RE=/^[A-Za-z0-9][A-Za-z0-9._:-]{0,127}$/;function clip(value,max=500){const text=String(value??'');return text.length>max?text.slice(0,max)+'…':text}function clippedJson(value,max=2000){try{return clip(JSON.stringify(value),max)}catch{return'[unserializable]'}}function parseTaskCheckpoint(value){if(value&&typeof value==='object'&&!Array.isArray(value))return value;if(typeof value!=='string'||!value)return null;try{const parsed=JSON.parse(value);return parsed&&typeof parsed==='object'&&!Array.isArray(parsed)?parsed:null}catch{return null}}function taskLocator(taskId){return location.pathname+(taskId?'?task_id='+encodeURIComponent(taskId):'')}function taskRow(title,meta,state,failed=false){return '<div class="row"><strong>'+esc(clip(title,160))+'</strong><span class="meta">'+esc(clip(meta,2000))+'</span><span class="state '+(failed?'failed':'')+'">'+esc(clip(state,160))+'</span></div>'}function evidenceRows(evidence){let html='';for(const item of evidence?.sideEffects||[])html+=taskRow('Tool call '+clip(item.call_key,80),'logical '+clip(item.logical_invocation_count,20)+' · provider attempts '+clip(item.provider_attempt_count,20)+' · '+clip(item.updated_at,120),clip(item.status,80),['failed','uncertain'].includes(item.status));for(const item of evidence?.elicitations||[])html+=taskRow('Elicitation '+clip(item.id,80),clip(item.provider_id,80)+' / '+clip(item.tool_name,80)+' · '+clip(item.mode,30),clip(item.status,80),['attention_required','expired'].includes(item.status));for(const item of evidence?.resumeIntents||[])html+=taskRow('Resume generation '+clip(item.generation,20),clip(item.ticket_id,80)+' · '+clip(item.fiber_id||'pending',120),clip(item.status,80),Boolean(item.error_code));for(const item of evidence?.browserActions||[])html+=taskRow('Browser action '+String(Number(item.action_index)+1)+' · '+clip(item.action_kind,80),'cost '+clip(item.logical_step_cost,20)+' · attempts '+clip(item.attempt_count,20)+' · mutating '+clip(item.mutating,10),clip(item.state,80),item.state==='attention_required');return html}function renderRecoveredTask(data,requestedId){const task=data?.task||{};const progress=data?.snapshot||{};const checkpoint=parseTaskCheckpoint(task.checkpoint_json);const status=clip(task.status||checkpoint?.status||progress.status||'unknown',80);let html=taskRow('Task '+requestedId,'generation '+clip(task.repair_generation??0,20)+' · updated '+clip(task.updated_at||progress.updatedAt||'unknown',120),status,['failed','cancelled','attention_required'].includes(status));html+=taskRow('Progress snapshot / event','revision '+clip(progress.revision??0,20)+' · phase '+clip(progress.phase||'unknown',80)+' · updated '+clip(progress.updatedAt||'unknown',120),clip(progress.eventType||progress.status||'no event',120));if(progress.detail&&typeof progress.detail==='object')html+=taskRow('Progress detail',clippedJson(progress.detail,2000),'read only');if(!checkpoint)return html+taskRow('Checkpoint','checkpoint unavailable or invalid','unavailable',true)+evidenceRows(data?.evidence);html+=taskRow('Checkpoint','round '+clip(checkpoint.round??0,20)+' · calls '+clip(checkpoint.callCount??0,20)+(checkpoint.error?' · '+clip(checkpoint.error,500):''),clip(checkpoint.status||status,80),checkpoint.status==='failed');if(checkpoint.pendingCall)html+=taskRow('Pending call',clip(checkpoint.pendingCall.serverId||'unknown',120)+' / '+clip(checkpoint.pendingCall.toolName||'unknown',120),'arguments hidden');const results=Array.isArray(checkpoint.results)?checkpoint.results.slice(-20):[];html+=results.map((result,index)=>taskRow('Result '+String(index+1)+' · '+clip(result?.toolName||'tool',120),clip(result?.note||'',400)+' · '+clip(result?.payload||'',4000),result?.truncated?'truncated':'sanitized')).join('');if(Array.isArray(checkpoint.results)&&checkpoint.results.length>results.length)html+=taskRow('Earlier results',String(checkpoint.results.length-results.length)+' result(s) omitted','limited');return html+evidenceRows(data?.evidence)}async function loadRecoveredTask(rawTaskId,{updateUrl=true}={}){const taskId=String(rawTaskId??'').trim();const target=$('#taskRecoveryResult');if(!TASK_ID_RE.test(taskId)){target.innerHTML=taskRow('Task ID','允许 1-128 位字母、数字、点、下划线、冒号或连字符','invalid',true);if(updateUrl)history.replaceState(null,'',taskLocator(''));return}$('#taskIdInput').value=taskId;if(updateUrl)history.replaceState(null,'',taskLocator(taskId));target.innerHTML='<div class="row"><span class="meta">正在从 Agent owner 读取 checkpoint</span></div>';try{const data=await api('/browser/e2e/'+encodeURIComponent(taskId));target.innerHTML=renderRecoveredTask(data,taskId)}catch(error){target.innerHTML=taskRow('Task '+taskId,clip(error?.message||'task lookup failed',500),'unavailable',true)}}$('#taskRecoveryForm').addEventListener('submit',event=>{event.preventDefault();loadRecoveredTask($('#taskIdInput').value).catch(()=>{})});const locatedTaskId=new URLSearchParams(location.search).get('task_id');if(locatedTaskId)queueMicrotask(()=>loadRecoveredTask(locatedTaskId,{updateUrl:true}));else if(location.search||location.hash)history.replaceState(null,'',taskLocator(''));`;
  const browserSkillsSection = `<section class="section"><h2>受限 Skills</h2><div class="rows" id="skills"><div class="row"><span class="meta">暂无 Skill</span></div></div></section>`;
  const browserSkillsScript = `$('#skills').innerHTML=(d.skills||[]).map(s=>'<div class="row"><strong>'+esc(s.key)+'</strong><span class="meta">'+esc(s.description)+' · '+esc(String(s.sourceHash||'').slice(0,12))+'</span><span class="state">'+esc(s.kind)+'</span></div>').join('')||'<div class="row"><span class="meta">暂无 Skill</span></div>';`;
  const browserOnlyBody = diagnosticBody.replace(browserSkillsSection, "");
  const browserOnlyScript = script.replace('renderDomains(b);', 'renderDomains(b);renderDomainPolicy(b);').replace(browserSkillsScript, "");
  return pageShell(`Browser & Web · ${quickActionNames}`, "browser", browserOnlyBody, `${browserOnlyScript}${smokeScript}${domainScript}${domainPolicyScript}${plannerScript}${recoveryScript}`, links);
}

export function renderHooksWorkbenchPage(csrfToken = "", links: readonly ControlLink[] = []): Response {
  const eventOptions = ["before_plan", "before_tool", "before_browser_action", "after_tool", "on_error", "on_approval", "on_heartbeat", "before_companion_pulse", "after_companion_pulse"].map((value) => `<option value="${value}">${value}</option>`).join("");
  const body = `<header><div><div class="meta">ORCHESTRATION / EXTENSIONS</div><h1>Hooks & Heartbeat</h1></div><button class="action" id="heartbeat" type="button">运行 Heartbeat</button></header><form id="hookForm"><div class="field"><label for="event">事件</label><select id="event">${eventOptions}</select></div><div class="field"><label for="mode">模式</label><select id="mode"><option value="advisory">advisory</option><option value="gate">gate</option></select></div><div class="field"><label for="target">目标</label><select id="target"><option value="builtin">内置 Handler</option><option value="webhook">签名 Webhook</option></select></div><div class="field"><label for="handler">内置 Handler</label><select id="handler"><option value="builtin:noop">noop</option><option value="builtin:allow">allow</option><option value="builtin:deny">deny</option></select></div><div class="field wide" id="urlField" hidden><label for="url">Webhook URL</label><input id="url" type="url" placeholder="https://hooks.example.com/operia"></div><div class="field wide"><label for="filter">过滤器 JSON</label><textarea id="filter" spellcheck="false">{}</textarea></div><div class="field"><label for="failure">失败策略</label><select id="failure"><option value="fail-open">fail-open</option><option value="fail-closed">fail-closed</option></select></div><div class="field"><label><input id="enabled" type="checkbox" checked> 创建后启用</label></div><div class="actions wide"><button class="action primary" type="submit">新增 Hook</button><span class="hint">Webhook 使用服务端共享签名 secret；浏览器不会接触密钥。</span></div></form><section class="section"><h2>已配置 Hooks</h2><div class="rows" id="hooks"><div class="row"><span class="meta">暂无 Hook</span></div></div></section><section class="section"><h2>Heartbeat</h2><div class="rows" id="heartbeatState"><div class="row"><span class="meta">尚无记录</span></div></div></section>`;
  const script = `${sharedScript};let csrf=${JSON.stringify(csrfToken)};async function load(){const d=await api('/bootstrap');if(!csrf&&d.csrfToken)csrf=String(d.csrfToken);$('#hooks').innerHTML=(d.hooks||[]).map(h=>'<div class="row"><strong>'+esc(h.event)+' · '+esc(h.mode)+'</strong><span class="meta">'+esc(h.target_type)+' · '+esc(h.owner_id)+'/'+esc(h.service_id)+'</span><span><button class="action toggle" data-id="'+esc(h.id)+'" data-enabled="'+(h.enabled?'1':'0')+'" type="button">'+(h.enabled?'停用':'启用')+'</button> <button class="action danger delete" data-id="'+esc(h.id)+'" type="button" title="删除 Hook">×</button></span></div>').join('')||'<div class="row"><span class="meta">暂无 Hook</span></div>';const hb=d.heartbeat;$('#heartbeatState').innerHTML=hb?'<div class="row"><strong>'+esc(hb.createdAt)+'</strong><span class="meta">stale '+esc(hb.staleTasks||0)+' · approval '+esc(hb.expiredApprovals||0)+'</span><span class="state">browser '+esc(hb.browserMsToday||0)+'ms</span></div>':'<div class="row"><span class="meta">尚无记录</span></div>'}function mutation(path,options){return api(path,{...options,headers:{'content-type':'application/json','x-csrf-token':csrf,...(options.headers||{})}})}$('#target').addEventListener('change',()=>{$('#urlField').hidden=$('#target').value!=='webhook';$('#handler').disabled=$('#target').value==='webhook'});$('#hookForm').addEventListener('submit',async e=>{e.preventDefault();try{const filter=JSON.parse($('#filter').value||'{}');const target=$('#target').value==='webhook'?{type:'webhook',url:$('#url').value}:{type:'builtin',handler:$('#handler').value};await mutation('/hooks',{method:'POST',body:JSON.stringify({event:$('#event').value,mode:$('#mode').value,failurePolicy:$('#failure').value,enabled:$('#enabled').checked,filter,target})});toast('Hook 已创建');await load()}catch(e){toast(e.message)}});$('#hooks').addEventListener('click',async e=>{const toggle=e.target.closest('.toggle');if(toggle){try{await mutation('/hooks/'+encodeURIComponent(toggle.dataset.id)+'/toggle',{method:'POST',body:JSON.stringify({enabled:toggle.dataset.enabled!=='1'})});toast('Hook 状态已更新');await load()}catch(error){toast(error.message)}return}const b=e.target.closest('.delete');if(!b)return;if(!confirm('删除这个 Hook？'))return;try{await mutation('/hooks/'+encodeURIComponent(b.dataset.id),{method:'DELETE'});toast('Hook 已删除');await load()}catch(error){toast(error.message)}});$('#heartbeat').addEventListener('click',async()=>{try{await mutation('/heartbeat',{method:'POST',body:'{}'});toast('Heartbeat 已完成');await load()}catch(e){toast(e.message)}});load().catch(e=>toast(e.message));`;
  return pageShell("Hooks & Heartbeat", "hooks", body, script, links);
}

export function renderHeartbeatStudioPage(csrfToken = "", links: readonly ControlLink[] = []): Response {
  const body = `<header><div><div class="meta">AUTOMATION / COMPANION</div><h1>Heartbeat Studio</h1><p class="hint">Agent 是唯一配置真源；Observe 只记录活动，Active 必须回到 Telegram 明确授权。</p></div><span class="state" id="ownerState">connecting</span></header><form id="configForm"><div class="field"><label for="mode">模式</label><select id="mode"><option value="off">Off</option><option value="observe">Observe</option><option value="active">Active（请求 Telegram 授权）</option></select></div><div class="field"><label for="timezone">时区</label><input id="timezone" value="<YOUR_TIMEZONE>"></div><div class="field"><label for="quietStart">静默开始</label><input id="quietStart" type="time"></div><div class="field"><label for="quietEnd">静默结束</label><input id="quietEnd" type="time"></div><div class="field"><label for="pulseHours">Pulse 小时（逗号）</label><input id="pulseHours" placeholder="10,15,20"></div><div class="field"><label for="dailyLimit">每日额度</label><input id="dailyLimit" type="number" min="0" max="3"></div><div class="field"><label for="jitter">随机抖动分钟</label><input id="jitter" type="number" min="0" max="59"></div><div class="field"><label><input id="dryRun" type="checkbox"> 所有 Pulse dry-run</label></div><div class="field wide"><label for="prompt">自定义提示词（不能提权）</label><textarea id="prompt" maxlength="4000"></textarea></div><div class="field wide"><label>自主能力（全部只能收紧）</label><span><label><input class="cap" data-key="say" type="checkbox">说话</label> <label><input class="cap" data-key="operiaRead" type="checkbox">Operia只读</label> <label><input class="cap" data-key="mcpRead" type="checkbox">MCP只读</label> <label><input class="cap" data-key="search" type="checkbox">搜索</label> <label><input class="cap" data-key="browserRead" type="checkbox">Browser只读</label></span></div><div class="actions wide"><button class="action primary" type="submit">保存配置</button><button class="action" id="dryRunNow" type="button">立即 dry-run</button><button class="action" id="runNow" type="button">立即运行</button><a class="action" href="https://tgbot.example.com/admin#heartbeat">前往 Telegram 授权</a></div></form><section class="section"><h2>Runtime</h2><div class="rows" id="runtime"></div></section><section class="section"><h2>Intent 与决策日志</h2><div class="rows" id="events"></div></section>`;
  const script = `${sharedScript};let csrf=${JSON.stringify(csrfToken)},revision=0,current={};function mutation(path,options){return api(path,{...options,headers:{'content-type':'application/json','x-csrf-token':csrf,...(options.headers||{})}})}function row(title,meta,state){return '<div class="row"><strong>'+esc(title)+'</strong><span class="meta">'+esc(meta)+'</span><span class="state">'+esc(state)+'</span></div>'}function parsed(value){try{return typeof value==='string'?JSON.parse(value):value||{}}catch{return{}}}async function load(){const d=await api('/heartbeat/bootstrap');if(!csrf&&d.csrfToken)csrf=String(d.csrfToken);revision=Number(d.revision||0);current=d.config||{};$('#ownerState').textContent='owner_store · r'+revision;$('#mode').value=current.mode||'armed';$('#timezone').value=current.timezone||"<YOUR_TIMEZONE>";$('#quietStart').value=current.quietHours?.start||'23:00';$('#quietEnd').value=current.quietHours?.end||'08:00';$('#pulseHours').value=(current.pulseHours||[]).join(',');$('#dailyLimit').value=current.dailyLimit??3;$('#jitter').value=current.jitterMinutes??25;$('#dryRun').checked=Boolean(current.dryRun);$('#prompt').value=current.prompt||'';document.querySelectorAll('.cap').forEach(x=>x.checked=current.capabilities?.[x.dataset.key]!==false);const r=d.runtime||{};$('#runtime').innerHTML=row('Mode',r.lastRealActivityAt||'尚无真实活动',r.mode||'unknown')+row('Daily pulse',String(r.pulsesUsed||0)+' / '+String(current.dailyLimit??3),r.localDate||'')+row('First pulse',r.firstPulseDryRunPending?'首次强制 dry-run':'已完成首次 dry-run',r.activatedAt||'not active');const logs=await api('/heartbeat/events');const intentRows=(logs.intents||[]).map(x=>row(x.kind+' · '+x.id,x.created_at+' · attempts '+x.attempts,x.status+(x.dry_run?' · dry-run':'')));const eventRows=(logs.events||[]).map(x=>{const u=parsed(x.usage_json);return row(x.event_type+' · '+(x.intent_id||'activity'),x.created_at+' · in '+(u.input_tokens??'-')+' · out '+(u.output_tokens??'-')+' · cache '+(u.cache_read_input_tokens??u.cache_read_tokens??'-'),String(x.duration_ms??0)+'ms')});$('#events').innerHTML=[...eventRows,...intentRows].join('')||row('暂无 intent','','idle')}$('#configForm').addEventListener('submit',async e=>{e.preventDefault();const capabilities={};document.querySelectorAll('.cap').forEach(x=>capabilities[x.dataset.key]=x.checked);const config={...current,mode:$('#mode').value,timezone:$('#timezone').value.trim(),quietHours:{start:$('#quietStart').value,end:$('#quietEnd').value},pulseHours:$('#pulseHours').value.split(',').map(Number),dailyLimit:Number($('#dailyLimit').value),jitterMinutes:Number($('#jitter').value),dryRun:$('#dryRun').checked,prompt:$('#prompt').value,capabilities};try{await mutation('/heartbeat/config',{method:'PUT',headers:{'if-match':'"'+revision+'"','idempotency-key':crypto.randomUUID()},body:JSON.stringify({config})});toast('Heartbeat 配置已保存');await load()}catch(error){toast(error.message)}});$('#dryRunNow').onclick=async()=>{try{await mutation('/heartbeat/dry-run',{method:'POST',body:'{}'});toast('dry-run intent 已创建');await load()}catch(error){toast(error.message)}};$('#runNow').onclick=async()=>{try{if(!confirm('立即运行一次 Companion Pulse？off/armed 会拒绝。'))return;await mutation('/heartbeat/run-now',{method:'POST',body:'{}'});toast('run intent 已创建');await load()}catch(error){toast(error.message)}};load().catch(error=>toast(error.message));`;
  return pageShell("Operia Heartbeat Studio", "heartbeat", body, script, links);
}

export function renderSkillsWorkbenchPage(csrfToken = "", links: readonly ControlLink[] = []): Response {
  const body = `<header><div><div class="meta">EXTENSIONS / SIGNED REGISTRY</div><h1>Skills</h1></div><span class="state" id="cutover">正在连接</span></header><div class="stats"><div class="stat"><strong id="installedCount">-</strong><span class="meta">Installed</span></div><div class="stat"><strong id="publisherCount">-</strong><span class="meta">Publishers</span></div><div class="stat"><strong id="runCount">-</strong><span class="meta">Durable runs</span></div><div class="stat"><strong id="executor">off</strong><span class="meta">Executor</span></div></div><section class="section"><h2>Installed</h2><div class="rows" id="installed"><div class="row"><span class="meta">暂无安装</span></div></div></section><section class="section"><h2>Publisher trust root</h2><form id="publisherForm"><div class="field"><label for="keyId">Key ID</label><input id="keyId" required maxlength="128" spellcheck="false"></div><div class="field"><label for="registry">Registry URL</label><input id="registry" required type="url" placeholder="https://registry.example"></div><div class="field wide"><label for="publicKey">Ed25519 public key · base64url</label><input id="publicKey" required spellcheck="false"></div><div class="actions wide"><button class="action primary" type="submit">保存 Publisher</button><span class="hint">Registry 必须先进入 Worker 精确 allowlist；浏览器只提交公钥。</span></div></form><div class="rows" id="publishers"><div class="row"><span class="meta">暂无 Publisher</span></div></div></section><section class="section"><h2>Community install</h2><form id="installForm"><div class="field"><label for="alias">Alias</label><input id="alias" required pattern="[a-z0-9][a-z0-9_]{0,63}" spellcheck="false"></div><div class="field wide"><label for="envelope">Signed envelope JSON</label><textarea id="envelope" required spellcheck="false">{}</textarea></div><div class="actions wide"><button class="action primary" type="submit">验证并安装</button><span class="hint">安装后固定为 disabled；另行审核并启用。版本不可覆盖。</span></div></form></section><section class="section"><h2>Runs</h2><div class="rows" id="runs"><div class="row"><span class="meta">暂无 run</span></div></div></section><section class="section"><h2>Audit</h2><div class="rows" id="events"><div class="row"><span class="meta">暂无事件</span></div></div></section>`;
  const script = `const API='/api/agent/skills';const $=s=>document.querySelector(s);const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));let csrf=${JSON.stringify(csrfToken)};function toast(m){const n=$('#toast');n.textContent=m;n.classList.add('show');setTimeout(()=>n.classList.remove('show'),2200)}async function api(path,options={}){const response=await fetch(API+path,{credentials:'same-origin',...options,headers:{accept:'application/json',...(options.headers||{})}});const data=await response.json();if(!response.ok)throw new Error(data.code||data.error||response.statusText);return data}function mutation(path,options){return api(path,{...options,headers:{'content-type':'application/json','x-csrf-token':csrf,...(options.headers||{})}})}async function load(){const d=await api('/bootstrap');if(!csrf&&d.csrfToken)csrf=d.csrfToken;const installed=d.installed||[],publishers=d.publishers||[],runs=d.runs||[];$('#cutover').textContent=d.executionCutover||'unknown';$('#installedCount').textContent=installed.length;$('#publisherCount').textContent=publishers.length;$('#runCount').textContent=runs.length;$('#executor').textContent=d.executorEnabled?'on':'off';$('#installed').innerHTML=installed.map(x=>'<div class="row"><strong>'+esc(x.alias)+' · '+esc(x.skill_key)+'@'+esc(x.pinned_version)+'</strong><span class="meta">'+esc(x.source_type)+' · '+esc(x.trust_status)+' · '+esc(String(x.manifest_hash).slice(0,20))+' · revision '+esc(x.revision)+'</span><button class="action toggle" data-key="'+esc(x.skill_key)+'" data-revision="'+esc(x.revision)+'" data-enabled="'+esc(x.enabled)+'" type="button">'+(x.enabled?'停用':'启用')+'</button></div>').join('')||'<div class="row"><span class="meta">暂无安装</span></div>';$('#publishers').innerHTML=publishers.map(x=>'<div class="row"><strong>'+esc(x.key_id)+'</strong><span class="meta">'+esc(x.source_registry)+' · '+esc(x.fingerprint)+'</span><span class="state '+(x.status==='active'?'':'disabled')+'">'+esc(x.status)+'</span></div>').join('')||'<div class="row"><span class="meta">暂无 Publisher</span></div>';$('#runs').innerHTML=runs.map(x=>'<div class="row"><strong>'+esc(x.skill_key)+' · '+esc(x.id)+'</strong><span class="meta">'+esc(x.created_at)+' · '+esc(x.planned_call_json||x.blocked_code||'none')+'</span><span><span class="state '+(x.status==='blocked'?'failed':'')+'">'+esc(x.status)+'</span> '+(x.status==='planned'?'<button class="action cancel" data-id="'+esc(x.id)+'" type="button">取消</button>':'')+'</span></div>').join('')||'<div class="row"><span class="meta">暂无 run</span></div>';$('#events').innerHTML=(d.events||[]).map(x=>'<div class="row"><strong>'+esc(x.event_type)+'</strong><span class="meta">'+esc(x.skill_key)+' · '+esc(x.created_at)+'</span><span class="state">audit</span></div>').join('')||'<div class="row"><span class="meta">暂无事件</span></div>'}$('#publisherForm').addEventListener('submit',async e=>{e.preventDefault();try{await mutation('/publishers',{method:'POST',body:JSON.stringify({keyId:$('#keyId').value.trim(),sourceRegistry:$('#registry').value.trim(),publicKeyBase64Url:$('#publicKey').value.trim(),status:'active'})});toast('Publisher 已保存');await load()}catch(error){toast(error.message)}});$('#installForm').addEventListener('submit',async e=>{e.preventDefault();try{await mutation('/install',{method:'POST',body:JSON.stringify({alias:$('#alias').value.trim(),envelope:JSON.parse($('#envelope').value)})});toast('Skill 已验证并以 disabled 安装');await load()}catch(error){toast(error.message)}});$('#installed').addEventListener('click',async e=>{const b=e.target.closest('.toggle');if(!b)return;try{await mutation('/installations/'+encodeURIComponent(b.dataset.key),{method:'PUT',headers:{'if-match':'"'+b.dataset.revision+'"'},body:JSON.stringify({enabled:b.dataset.enabled!=='1'})});toast('Installation 已更新');await load()}catch(error){toast(error.message)}});$('#runs').addEventListener('click',async e=>{const b=e.target.closest('.cancel');if(!b)return;try{await mutation('/runs/'+encodeURIComponent(b.dataset.id)+'/cancel',{method:'POST',body:'{}'});toast('Run 已取消');await load()}catch(error){toast(error.message)}});load().catch(error=>{$('#cutover').textContent='unavailable';$('#cutover').classList.add('failed');toast(error.message)});`;
  return pageShell("Operia Skills", "skills", body, script, links);
}
